package com.alsafa.native4;

import android.app.Activity;import android.text.InputType;import android.view.Gravity;import android.view.View;import android.view.ViewGroup;import android.widget.ArrayAdapter;import android.widget.Button;import android.widget.EditText;import android.widget.LinearLayout;import android.widget.Spinner;import android.widget.TextView;import com.alsafa.native4.core.AccountingChoices;import com.alsafa.native4.core.DirectRepairPartSaleStore;import com.alsafa.native4.core.Native4BackgroundSync;import com.alsafa.native4.core.Native4Services;import com.alsafa.native4.core.SplitPaymentStore;import java.util.ArrayList;import java.util.List;
/** Native counter sale for repair parts/services with independent multi-currency payment legs. */
public final class DirectPartSalePanelBinder {
 private final Activity a;private final Native4Services services;private final TextView status;private final LinearLayout panel,paymentRows;private final EditText partId,quantity,unitPrice,serviceFee;private final Spinner currency;
 public DirectPartSalePanelBinder(Activity a,Native4Services services,TextView status,ViewGroup host){this.a=a;this.services=services;this.status=status;panel=new LinearLayout(a);panel.setOrientation(LinearLayout.VERTICAL);panel.setVisibility(View.GONE);TextView title=new TextView(a);title.setText("بيع قطعة صيانة / خدمة سريعة — بدون استلام ساعة");title.setTextSize(18);title.setGravity(Gravity.END);panel.addView(title);partId=field(a,"معرف/باركود قطعة الصيانة",InputType.TYPE_CLASS_TEXT);quantity=field(a,"الكمية",InputType.TYPE_CLASS_NUMBER);quantity.setText("1");unitPrice=field(a,"سعر القطعة",InputType.TYPE_CLASS_NUMBER|InputType.TYPE_NUMBER_FLAG_DECIMAL);serviceFee=field(a,"أجرة الخدمة (اختياري)",InputType.TYPE_CLASS_NUMBER|InputType.TYPE_NUMBER_FLAG_DECIMAL);currency=new Spinner(a);currency.setAdapter(new ArrayAdapter<>(a,android.R.layout.simple_spinner_dropdown_item,AccountingChoices.CURRENCY_LABELS));panel.addView(partId);panel.addView(quantity);LinearLayout amountRow=new LinearLayout(a);amountRow.setOrientation(LinearLayout.HORIZONTAL);amountRow.setGravity(Gravity.CENTER_VERTICAL);amountRow.addView(unitPrice,new LinearLayout.LayoutParams(0,ViewGroup.LayoutParams.WRAP_CONTENT,3f));amountRow.addView(currency,new LinearLayout.LayoutParams(0,ViewGroup.LayoutParams.WRAP_CONTENT,1f));panel.addView(amountRow);panel.addView(serviceFee);TextView paymentLabel=new TextView(a);paymentLabel.setText("الدفعات — لكل دفعة مبلغ وعملة ومكان تحصيل مستقل");paymentLabel.setGravity(Gravity.END);panel.addView(paymentLabel);paymentRows=new LinearLayout(a);paymentRows.setOrientation(LinearLayout.VERTICAL);panel.addView(paymentRows);Button add=new Button(a);add.setText("+ إضافة دفعة أخرى");add.setOnClickListener(v->addPaymentRow());panel.addView(add);addPaymentRow();Button save=new Button(a);save.setText("حفظ بيع القطعة / الخدمة");save.setOnClickListener(v->save());panel.addView(save);host.addView(panel);}
 public void show(boolean visible){panel.setVisibility(visible?View.VISIBLE:View.GONE);}
 private void addPaymentRow(){LinearLayout box=new LinearLayout(a);box.setOrientation(LinearLayout.VERTICAL);EditText amount=field(a,"المبلغ المقبوض",InputType.TYPE_CLASS_NUMBER|InputType.TYPE_NUMBER_FLAG_DECIMAL);Spinner cur=new Spinner(a);cur.setAdapter(new ArrayAdapter<>(a,android.R.layout.simple_spinner_dropdown_item,AccountingChoices.CURRENCY_LABELS));Spinner account=new Spinner(a);account.setAdapter(new ArrayAdapter<>(a,android.R.layout.simple_spinner_dropdown_item,new String[]{"الدرج","شام كاش","الخزنة الخارجية","البنك"}));Button remove=new Button(a);remove.setText("حذف الدفعة");remove.setOnClickListener(v->{if(paymentRows.getChildCount()>1)paymentRows.removeView(box);else amount.setText("");});box.addView(amount);box.addView(cur);box.addView(account);box.setTag(new PaymentViews(amount,cur,account));box.addView(remove);paymentRows.addView(box);}
 private List<SplitPaymentStore.Payment> readPayments(){List<SplitPaymentStore.Payment> out=new ArrayList<>();for(int i=0;i<paymentRows.getChildCount();i++){PaymentViews p=(PaymentViews)paymentRows.getChildAt(i).getTag();String raw=p.amount.getText().toString().trim();if(raw.isEmpty())continue;double amount=Double.parseDouble(raw);String cur=AccountingChoices.codeAt(AccountingChoices.CURRENCY_CODES,p.currency.getSelectedItemPosition());String acc=accountCode(p.account.getSelectedItemPosition());String method="SHAM_CASH".equals(acc)?"SHAM_CASH":"CASH";out.add(new SplitPaymentStore.Payment(amount,cur,method,acc));}return out;}
 private void save(){try{String pid=partId.getText().toString().trim();int q=Integer.parseInt(quantity.getText().toString().trim());double price=num(unitPrice),fee=num(serviceFee);String cur=AccountingChoices.codeAt(AccountingChoices.CURRENCY_CODES,currency.getSelectedItemPosition());List<SplitPaymentStore.Payment> payments=readPayments();DirectRepairPartSaleStore.Result r=services.directPartSales.sellSplit(pid,q,price,fee,cur,payments);Native4BackgroundSync.request(a);DeveloperDashboardPanelBinder.refreshActive();partId.setText("");quantity.setText("1");unitPrice.setText("");serviceFee.setText("");paymentRows.removeAllViews();addPaymentRow();status.setText("✓ بيع مباشر: "+r.partName+" — الإجمالي "+fmt(r.total)+" "+r.currency+" — الدفعات "+r.paymentCount+" — المتبقي بالحساب "+fmt(r.balanceUsd)+" USD — رصيد القطعة "+r.remainingQty);}catch(Exception e){status.setText("لم يُحفظ البيع المباشر: "+msg(e));}}
 private static String accountCode(int p){if(p==1)return "SHAM_CASH";if(p==2)return "EXTERNAL";if(p==3)return "BANK";return "MAIN";}private static final class PaymentViews{final EditText amount;final Spinner currency,account;PaymentViews(EditText a,Spinner c,Spinner ac){amount=a;currency=c;account=ac;}}
 private static EditText field(Activity a,String hint,int type){EditText e=new EditText(a);e.setHint(hint);e.setInputType(type);e.setGravity(Gravity.END);e.setLayoutParams(new ViewGroup.LayoutParams(ViewGroup.LayoutParams.MATCH_PARENT,ViewGroup.LayoutParams.WRAP_CONTENT));return e;}private static double num(EditText e){String s=e.getText().toString().trim();return s.isEmpty()?0:Double.parseDouble(s);}private static String fmt(double v){return String.format(java.util.Locale.US,"%.2f",v);}private static String msg(Exception e){return e.getMessage()==null?e.getClass().getSimpleName():e.getMessage();}
}
